create table public.export_receipts(id uuid primary key default gen_random_uuid(),actor_id uuid not null references public.profiles(id) on delete cascade,request_id uuid not null,kind text not null check(kind in ('reading','writing','drafts','exhibition','growth')),source_ids uuid[] not null check(cardinality(source_ids) between 1 and 100),format text not null check(format in ('docx','csv','print','google-docs','google-sheets')),title text not null check(length(title) between 1 and 100),external_url text check(external_url ~ '^https://docs\.google\.com/(document|spreadsheets)/d/[A-Za-z0-9_-]+(/edit(\?usp=drivesdk)?)?$'),state text not null check(state in ('generated','external','retained','removed')),note text not null default '' check(length(note)<=200),due_on date,revision integer not null default 0 check(revision>=0),created_at timestamptz not null default now(),unique(actor_id,request_id,format));
create index export_receipts_actor_created_idx on public.export_receipts(actor_id,created_at desc,id);
alter table public.export_receipts enable row level security;revoke all on public.export_receipts from public,anon,authenticated;grant select,insert on public.export_receipts to authenticated;grant update(state,note,due_on,revision) on public.export_receipts to authenticated;grant all on public.export_receipts to service_role;
create policy own_export_read on public.export_receipts for select to authenticated using ((select private.data_session()) and actor_id=(select auth.uid()));
create policy own_export_insert on public.export_receipts for insert to authenticated with check((select private.data_session()) and actor_id=(select auth.uid()));
create policy own_export_update on public.export_receipts for update to authenticated using ((select private.data_session()) and actor_id=(select auth.uid())) with check((select private.data_session()) and actor_id=(select auth.uid()));
create function public.register_export_receipt(p_kind text,p_ids uuid[],p_format text,p_title text,p_url text,p_request_id uuid) returns uuid language plpgsql security invoker set search_path='' as $$
declare visible_count integer;receipt public.export_receipts;out_id uuid;
begin if not private.data_session() then raise exception 'BF_FORBIDDEN';end if;
 if p_request_id is null or coalesce(cardinality(p_ids),0) not between 1 and 100 or (select count(distinct x) from unnest(p_ids)x)<>cardinality(p_ids) then raise exception 'BF_INVALID_INPUT';end if;
 case p_kind when 'reading' then select count(*) into visible_count from public.reading_logs where id=any(p_ids);when 'writing' then select count(*) into visible_count from public.submissions where id=any(p_ids);when 'drafts' then select count(*) into visible_count from public.drafts where id=any(p_ids);when 'exhibition' then select count(*) into visible_count from public.exhibition_entries where id=any(p_ids);when 'growth' then select count(*) into visible_count from public.term_reports where id=any(p_ids);else raise exception 'BF_INVALID_INPUT';end case;
 if visible_count<>cardinality(p_ids) then raise exception 'BF_FORBIDDEN';end if;
 insert into public.export_receipts(actor_id,request_id,kind,source_ids,format,title,external_url,state) values(auth.uid(),p_request_id,p_kind,p_ids,p_format,p_title,p_url,case when p_url is null then 'generated' else 'external' end) on conflict(actor_id,request_id,format) do nothing returning id into out_id;
 if out_id is null then select * into receipt from public.export_receipts where actor_id=auth.uid() and request_id=p_request_id and format=p_format;if receipt.kind<>p_kind or receipt.source_ids<>p_ids or receipt.title<>p_title or receipt.external_url is distinct from p_url then raise exception 'BF_IDEMPOTENCY_CONFLICT';end if;out_id:=receipt.id;end if;return out_id;
end $$;
revoke all on function public.register_export_receipt(text,uuid[],text,text,text,uuid) from public,anon;grant execute on function public.register_export_receipt(text,uuid[],text,text,text,uuid) to authenticated;
create function public.update_export_receipt(p_id uuid,p_revision integer,p_state text,p_due date,p_note text) returns void language plpgsql security invoker set search_path='' as $$
begin if p_state not in ('retained','removed') then raise exception 'BF_INVALID_INPUT';end if;update public.export_receipts set state=p_state,due_on=p_due,note=p_note,revision=revision+1 where id=p_id and revision=p_revision;if not found then raise exception 'BF_RECEIPT_CONFLICT';end if;end $$;
revoke all on function public.update_export_receipt(uuid,integer,text,date,text) from public,anon;grant execute on function public.update_export_receipt(uuid,integer,text,date,text) to authenticated;
create table public.privacy_reviews(id uuid primary key,classroom_id uuid not null references public.classrooms(id) on delete cascade,reviewed_by uuid references public.profiles(id) on delete set null,note text not null check(length(note) between 1 and 200),retention_days integer not null check(retention_days between 30 and 3650),created_at timestamptz not null default now());
create index privacy_reviews_class_time_idx on public.privacy_reviews(classroom_id,created_at desc,id);create index privacy_reviews_actor_idx on public.privacy_reviews(reviewed_by);
alter table public.privacy_reviews enable row level security;revoke all on public.privacy_reviews from public,anon,authenticated;grant select,insert on public.privacy_reviews to authenticated;grant all on public.privacy_reviews to service_role;
create policy class_privacy_read on public.privacy_reviews for select to authenticated using ((select private.data_session()) and (private.is_teacher(classroom_id) or private.is_operator()));
create policy class_privacy_insert on public.privacy_reviews for insert to authenticated with check((select private.data_session()) and reviewed_by=(select auth.uid()) and (private.is_teacher(classroom_id) or private.is_operator()) and (not private.is_operator() or private.operator_step_up_recent()));
create function public.review_privacy_policy(p_classroom uuid,p_days integer,p_note text,p_confirmed boolean,p_request_id uuid) returns void language plpgsql security invoker set search_path='' as $$
declare old public.privacy_reviews;
begin if p_confirmed is distinct from true or p_request_id is null then raise exception 'BF_CONFIRM_REQUIRED';end if;
 insert into public.privacy_reviews(id,classroom_id,reviewed_by,note,retention_days) values(p_request_id,p_classroom,auth.uid(),p_note,p_days) on conflict(id) do nothing;
 select * into old from public.privacy_reviews where id=p_request_id;
 if old is null or old.classroom_id<>p_classroom or old.note<>p_note or old.retention_days<>p_days or old.reviewed_by<>auth.uid() then raise exception 'BF_IDEMPOTENCY_CONFLICT';end if;
 perform public.operations_command('retention_set',jsonb_build_object('classroomId',p_classroom,'days',p_days),p_request_id);
end $$;
revoke all on function public.review_privacy_policy(uuid,integer,text,boolean,uuid) from public,anon;grant execute on function public.review_privacy_policy(uuid,integer,text,boolean,uuid) to authenticated;
create function public.privacy_policy_state() returns jsonb language plpgsql stable security definer set search_path='' as $$
begin if not private.data_session() then raise exception 'BF_FORBIDDEN';end if;return coalesce((select jsonb_agg(to_jsonb(x)) from(select c.id,c.name,r.days retention_days,v.note,v.created_at reviewed_at,(v.retention_days=r.days) current_review from public.classrooms c left join private.retention_policies r on r.classroom_id=c.id left join lateral(select * from public.privacy_reviews where classroom_id=c.id order by created_at desc,id desc limit 1)v on true where private.is_teacher(c.id) or private.is_operator() order by c.name,c.id limit 1000)x),'[]');end $$;
revoke all on function public.privacy_policy_state() from public,anon;grant execute on function public.privacy_policy_state() to authenticated;
